refentry.refsect1:
  &reftitle.examples;

   Envio de mensagens de manutenção da conexão


<?php
$connection = ssh2_connect('shell.example.com', 22);
ssh2_auth_password($connection, 'username', 'password');

// Solicita uma resposta do servidor após 30 segundos sem tráfego
ssh2_keepalive_config($connection, true, 30);

// As mensagens de manutenção da conexão só são enviadas quando esta função é chamada
ssh2_keepalive_send($connection);
?>
